import Uint64 = require( '@stdlib/number/uint64/ctor' );
import xor = require( './index' );


// TESTS //

// The function returns a 64-bit unsigned integer...
{
	const a = new Uint64( 5 );

	xor( a, a ); // $ExpectType Uint64
}

// The compiler throws an error if the function is provided a first argument which is not a 64-bit unsigned integer...
{
	const a = new Uint64( 5 );

	xor( true, a ); // $ExpectError
	xor( false, a ); // $ExpectError
	xor( null, a ); // $ExpectError
	xor( undefined, a ); // $ExpectError
	xor( '5', a ); // $ExpectError
	xor( [], a ); // $ExpectError
	xor( {}, a ); // $ExpectError
	xor( ( x: number ): number => x, a ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a 64-bit unsigned integer...
{
	const a = new Uint64( 5 );

	xor( a, true ); // $ExpectError
	xor( a, false ); // $ExpectError
	xor( a, null ); // $ExpectError
	xor( a, undefined ); // $ExpectError
	xor( a, '5' ); // $ExpectError
	xor( a, [] ); // $ExpectError
	xor( a, {} ); // $ExpectError
	xor( a, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const a = new Uint64( 5 );

	xor(); // $ExpectError
	xor( a ); // $ExpectError
	xor( a, a, a ); // $ExpectError
}

// Attached to the main export is an `assign` method which returns a collection...
{
	xor.assign( 1, 2, 3, 4, new Uint32Array( 2 ), 1, 0 ); // $ExpectType Uint32Array
	xor.assign( 1, 2, 3, 4, new Float64Array( 2 ), 1, 0 ); // $ExpectType Float64Array
	xor.assign( 1, 2, 3, 4, [ 0, 0 ], 1, 0 ); // $ExpectType number[]
}

// The compiler throws an error if the `assign` method is provided a first argument which is not a number...
{
	const out = new Uint32Array( 2 );

	xor.assign( true, 2, 3, 4, out, 1, 0 ); // $ExpectError
	xor.assign( false, 2, 3, 4, out, 1, 0 ); // $ExpectError
	xor.assign( null, 2, 3, 4, out, 1, 0 ); // $ExpectError
	xor.assign( undefined, 2, 3, 4, out, 1, 0 ); // $ExpectError
	xor.assign( '5', 2, 3, 4, out, 1, 0 ); // $ExpectError
	xor.assign( [], 2, 3, 4, out, 1, 0 ); // $ExpectError
	xor.assign( {}, 2, 3, 4, out, 1, 0 ); // $ExpectError
	xor.assign( ( x: number ): number => x, 2, 3, 4, out, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `assign` method is provided a second argument which is not a number...
{
	const out = new Uint32Array( 2 );

	xor.assign( 1, true, 3, 4, out, 1, 0 ); // $ExpectError
	xor.assign( 1, false, 3, 4, out, 1, 0 ); // $ExpectError
	xor.assign( 1, null, 3, 4, out, 1, 0 ); // $ExpectError
	xor.assign( 1, undefined, 3, 4, out, 1, 0 ); // $ExpectError
	xor.assign( 1, '5', 3, 4, out, 1, 0 ); // $ExpectError
	xor.assign( 1, [], 3, 4, out, 1, 0 ); // $ExpectError
	xor.assign( 1, {}, 3, 4, out, 1, 0 ); // $ExpectError
	xor.assign( 1, ( x: number ): number => x, 3, 4, out, 1, 0 ); // $ExpectError
}

